21: /**
22:  * All database access and approval decisions for the Document Approval Form.
23:  * <p>
24:  * The form itself only draws and collects input, so every rule about who may
25:  * approve which document lives here and can be reasoned about in one place.
26:  * <p>
27:  * The rules, as agreed with the business:
28:  * <ul>
29:  * <li>A document is offered to a user only when a row in
30:  * {@code XX_ReqDocType_Supervisor} maps that document type and its creator to
31:  * that user as the supervisor.</li>
32:  * <li>The amount of a document is the sum of its line amounts, because
33:  * {@code M_Requisition} has no amount column of its own.</li>
34:  * <li>{@code UpperLimit} of zero or less means no upper bound and a null
35:  * {@code LowerLimit} means zero, so a document always falls inside exactly one
36:  * band unless the data itself contradicts itself.</li>
37:  * </ul>
38:  * <p>
39:  * Every statement is parameterised; no value is ever pasted into SQL text.
40:  *
41:  * @author Shaharan Hossain
42:  */
43: public class DocumentApprovalService {
44: 
45: 	/** Physical table of the supervisor mapping. */
46: 	public static final String T_SUPERVISOR = "XX_REQDOCTYPE_SUPERVISOR";
47: 	/** Physical table of the approval history. */
48: 	public static final String T_HISTORY = "XX_APPROVAL_HISTORY";
49: 	/** The document table this form ships with; others plug in the same way. */
50: 	public static final String T_DOCUMENT = "M_REQUISITION";
51: 	/** Document status that means "still waiting for approval". */
52: 	private static final String PENDING = "DR";
53: 
54: 	/** Action words stored in the history table. */
55: 	public static final String ACTION_APPROVE = "APPROVE";
56: 	public static final String ACTION_REJECT = "REJECT";
57: 	public static final String ACTION_FORWARD = "FORWARD";
58: 
59: 	private static final CLogger log = CLogger.getCLogger(DocumentApprovalService.class);
60: 
61: 	/** The translation of a literal, looked up in the session language. */
62: 	private static String msg(String text) {
63: 		return Msg.translate(Env.getCtx(), text);
64: 	}
65: 
66: 	// ------------------------------------------------------------------
67: 	// Lookups for the search panel
68: 	// ------------------------------------------------------------------
69: 
70: 	/**
71: 	 * Document types this user could ever receive, that is the ones that have a
72: 	 * supervisor mapping. Offering any other type would return nothing.
73: 	 */
74: 	public List<String> documentTypeOptions() {
75: 		return strings("SELECT DISTINCT dt.Name "
76: 				+ "FROM " + T_SUPERVISOR + " m "
77: 				+ "JOIN C_DocType dt ON dt.C_DocType_ID = m.C_DocType_ID "
78: 				+ "WHERE m.AD_Client_ID = ? AND m.IsActive = 'Y' "
79: 				+ "ORDER BY dt.Name", false);
80: 	}
81: 
82: 	/** Organizations that have documents pending approval. */
83: 	public List<String> organizationOptions() {
84: 		return strings("SELECT DISTINCT o.Name "
85: 				+ "FROM " + T_SUPERVISOR + " m "
86: 				+ "JOIN " + T_DOCUMENT + " d ON d.C_DocType_ID = m.C_DocType_ID "
87: 				+ "JOIN AD_Org o ON o.AD_Org_ID = d.AD_Org_ID "
88: 				+ "WHERE m.AD_Client_ID = ? AND m.IsActive = 'Y' "
89: 				+ "ORDER BY o.Name", false);
90: 	}
91: 
92: 	/** Users a pending document may be forwarded to, other than the user themselves. */
93: 	public List<String> userOptions() {
94: 		return strings("SELECT Name FROM AD_User "
95: 				+ "WHERE IsActive = 'Y' AND AD_Client_ID IN (0, ?) "
96: 				+ "AND AD_User_ID <> ? ORDER BY Name", true);
97: 	}
98: 
99: 	/** Runs a one column query and returns its text values. */
100: 	private List<String> strings(String sql, boolean alsoCurrentUser) {
101: 		List<String> result = new ArrayList<String>();
102: 		PreparedStatement pstmt = null;
103: 		ResultSet rs = null;
104: 		try {
105: 			pstmt = DB.prepareStatement(sql, null);
106: 			pstmt.setInt(1, Env.getAD_Client_ID(Env.getCtx()));
107: 			if (alsoCurrentUser)
108: 				pstmt.setInt(2, Env.getAD_User_ID(Env.getCtx()));
109: 			rs = pstmt.executeQuery();
110: 			while (rs.next())
111: 				result.add(rs.getString(1));
112: 		} catch (SQLException e) {
113: 			log.warning("Lookup failed: " + sql + " -> " + e.getMessage());
114: 			result.clear();
115: 		} finally {
116: 			DB.close(rs);
117: 			DB.close(pstmt);
118: 		}
119: 		return result;
120: 	}
121: 
122: 	// ------------------------------------------------------------------
123: 	// The grid
124: 	// ------------------------------------------------------------------
125: 
126: 	/**
127: 	 * Documents waiting for this user's approval.
128: 	 *
129: 	 * @param from    inclusive lower bound on the document date, null for none
130: 	 * @param to      inclusive upper bound on the document date, null for none
131: 	 * @param orgName organization name, null or empty for all
132: 	 * @param docType document type name, null or empty for all
133: 	 * @param docNo   document number, null or empty for all
134: 	 * @param amount  exact amount, null for none
135: 	 * @return matching documents, newest first
136: 	 */
137: 	public List<ApprovalDocument> listPendingDocuments(Timestamp from, Timestamp to, String orgName,
138: 			String docType, String docNo, BigDecimal amount, String businessPartner) {
139: 
140: 		List<ApprovalDocument> result = new ArrayList<ApprovalDocument>();
141: 
142: 		StringBuilder sql = new StringBuilder();
143: 		sql.append("SELECT d.M_Requisition_ID, d.DocumentNo, d.C_DocType_ID, dt.Name, ")
144: 		   .append("       d.AD_Org_ID, o.Name, d.DateDoc, d.Created, d.CreatedBy, cu.Name, ")
145: 		   .append("       d.DocStatus, COALESCE(amt.Total, 0) AS Amount, d.RequisitionType, ")
146: 		   .append("       m.IsFinalApprover, bp.Name ")
147: 		   .append("FROM ").append(T_DOCUMENT).append(" d ")
148: 		   .append("JOIN ").append(T_SUPERVISOR).append(" m ")
149: 		   .append("     ON m.C_DocType_ID  = d.C_DocType_ID ")
150: 		   .append("    AND m.AD_User_ID    = d.CreatedBy ")
151: 		   .append("    AND m.Supervisor_ID = ? ")
152: 		   .append("    AND m.AD_Client_ID  = d.AD_Client_ID ")
153: 		   .append("    AND m.IsActive      = 'Y' ")
154: 		   .append("JOIN C_DocType dt ON dt.C_DocType_ID = d.C_DocType_ID ")
155: 		   .append("JOIN AD_Org     o  ON o.AD_Org_ID     = d.AD_Org_ID ")
156: 		   .append("LEFT JOIN AD_User cu ON cu.AD_User_ID = d.CreatedBy ")
157: 		   .append("LEFT JOIN (SELECT M_Requisition_ID, SUM(LineNetAmt) AS Total ")
158: 		   .append("             FROM M_RequisitionLine GROUP BY M_Requisition_ID) amt ")
159: 		   .append("       ON amt.M_Requisition_ID = d.M_Requisition_ID ")
160: 		   .append("LEFT JOIN (SELECT M_Requisition_ID, MIN(C_BPartner_ID) AS BPartner ")
161: 		   .append("             FROM M_RequisitionLine WHERE C_BPartner_ID > 0 ")
162: 		   .append("             GROUP BY M_Requisition_ID) bl ")
163: 		   .append("       ON bl.M_Requisition_ID = d.M_Requisition_ID ")
164: 		   .append("LEFT JOIN C_BPartner bp ON bp.C_BPartner_ID = bl.BPartner ")
165: 		   .append("WHERE d.AD_Client_ID = ? ")
166: 		   .append("  AND d.DocStatus = ? ");
167: 
168: 		// The optional filters are appended first so that their placeholders and
169: 		// the three fixed ones can be bound in one pass, in the same order.
170: 		if (from != null)
171: 			sql.append("  AND d.DateDoc >= ? ");
172: 		if (to != null)
173: 			sql.append("  AND d.DateDoc <= ? ");
174: 		if (isFilled(orgName))
175: 			sql.append("  AND o.Name = ? ");
176: 		if (isFilled(docType))
177: 			sql.append("  AND dt.Name = ? ");
178: 		if (isFilled(docNo))
179: 			sql.append("  AND d.DocumentNo LIKE ? ");
180: 		if (isFilled(businessPartner))
181: 			sql.append("  AND LOWER(bp.Name) LIKE ? ");
182: 		if (amount != null)
183: 			sql.append("  AND COALESCE(amt.Total, 0) = ? ");
184: 
185: 		// The band is part of the mapping, not of the search panel, so it is always
186: 		// applied: an approver may only see documents their own band covers.
187: 		sql.append("  AND COALESCE(amt.Total, 0) >= COALESCE(m.LowerLimit, 0) ")
188: 		   .append("  AND (m.UpperLimit IS NULL OR m.UpperLimit <= 0 ")
189: 		   .append("       OR COALESCE(amt.Total, 0) <= m.UpperLimit) ")
190: 		   .append("ORDER BY d.DateDoc DESC, d.DocumentNo");
191: 
192: 		PreparedStatement pstmt = null;
193: 		ResultSet rs = null;
194: 		try {
195: 			pstmt = DB.prepareStatement(sql.toString(), null);
196: 			int i = 1;
197: 			pstmt.setInt(i++, Env.getAD_User_ID(Env.getCtx()));
198: 			pstmt.setInt(i++, Env.getAD_Client_ID(Env.getCtx()));
199: 			pstmt.setString(i++, PENDING);
200: 			if (from != null)
201: 				pstmt.setTimestamp(i++, from);
202: 			if (to != null)
203: 				pstmt.setTimestamp(i++, to);
204: 			if (isFilled(orgName))
205: 				pstmt.setString(i++, orgName);
206: 			if (isFilled(docType))
207: 				pstmt.setString(i++, docType);
208: 			if (isFilled(docNo))
209: 				pstmt.setString(i++, docNo + "%");
210: 			if (isFilled(businessPartner))
211: 				pstmt.setString(i++, "%" + businessPartner.toLowerCase() + "%");
212: 			if (amount != null)
213: 				pstmt.setBigDecimal(i++, amount);
214: 
215: 			rs = pstmt.executeQuery();
216: 			int serial = 1;
217: 			while (rs.next()) {
218: 				ApprovalDocument d = new ApprovalDocument();
219: 				d.setSerialNo(serial++);
220: 				d.setId(rs.getInt(1));
221: 				d.setDocumentNo(rs.getString(2));
222: 				d.setDocTypeId(rs.getInt(3));
223: 				d.setDocTypeName(rs.getString(4));
224: 				d.setOrgId(rs.getInt(5));
225: 				d.setOrgName(rs.getString(6));
226: 				d.setReceiveDate(rs.getTimestamp(7));
227: 				d.setCreated(rs.getTimestamp(8));
228: 				d.setCreatedBy(rs.getInt(9));
229: 				d.setPreparedBy(rs.getString(10));
230: 				d.setDocStatus(rs.getString(11));
231: 				d.setAmount(rs.getBigDecimal(12));
232: 				d.setSalesType(rs.getString(13));
233: 				d.setFinalApprover("Y".equalsIgnoreCase(rs.getString(14)));
234: 				d.setBusinessPartner(rs.getString(15));
235: 				result.add(d);
236: 			}
237: 		} catch (SQLException e) {
238: 			log.warning("Could not list the pending documents: " + e.getMessage());
239: 			result.clear();
240: 		} finally {
241: 			DB.close(rs);
242: 			DB.close(pstmt);
243: 		}
244: 		return result;
245: 	}
246: 
247: 	// ------------------------------------------------------------------
248: 	// Decisions
249: 	// ------------------------------------------------------------------
250: 
251: 	/** True when the mapping marks this approver as the last one for the band. */
252: 	public boolean isFinalApprover(ApprovalDocument doc) {
253: 		return doc.isFinalApprover();
254: 	}
255: 
256: 	/**
257: 	 * The supervisor that takes over when the current approver is not final.
258: 	 * <p>
259: 	 * It is the supervisor named by the mapping row whose {@code AD_User_ID} is the
260: 	 * current approver, for the same document type. Null when the current approver
261: 	 * is the end of the chain.
262: 	 */
263: 	public Integer nextSupervisor(ApprovalDocument doc) {
264: 		Integer next = null;
265: 		PreparedStatement pstmt = null;
266: 		ResultSet rs = null;
267: 		try {
268: 			String sql = "SELECT MIN(m.Supervisor_ID) FROM " + T_SUPERVISOR + " m "
269: 					+ "WHERE m.AD_Client_ID = ? AND m.C_DocType_ID = ? "
270: 					+ "  AND m.AD_User_ID = ? AND m.IsActive = 'Y' "
271: 					+ "  AND COALESCE(m.Supervisor_ID, 0) <> ?";
272: 			pstmt = DB.prepareStatement(sql, null);
273: 			pstmt.setInt(1, Env.getAD_Client_ID(Env.getCtx()));
274: 			pstmt.setInt(2, doc.getDocTypeId());
275: 			pstmt.setInt(3, Env.getAD_User_ID(Env.getCtx()));
276: 			pstmt.setInt(4, Env.getAD_User_ID(Env.getCtx()));
277: 			rs = pstmt.executeQuery();
278: 			if (rs.next()) {
279: 				int value = rs.getInt(1);
280: 				next = rs.wasNull() ? null : Integer.valueOf(value);
281: 			}
282: 		} catch (SQLException e) {
283: 			log.warning("Could not find the next supervisor: " + e.getMessage());
284: 		} finally {
285: 			DB.close(rs);
286: 			DB.close(pstmt);
287: 		}
288: 		return next;
289: 	}
290: 
291: 	/**
292: 	 * Points the mapping of this document type and creator at a new approver.
293: 	 * <p>
294: 	 * The mapping table is what decides who approves, so forwarding is a change
295: 	 * of that row rather than a copy of the document.
296: 	 *
297: 	 * @return true when at least one mapping row was changed
298: 	 */
299: 	public boolean forward(ApprovalDocument doc, int toUserId) throws ApprovalException {
300: 		if (toUserId <= 0)
301: 			throw new ApprovalException(msg("No user was chosen to forward to."));
302: 		if (toUserId == Env.getAD_User_ID(Env.getCtx()))
303: 			throw new ApprovalException(msg("A document cannot be forwarded to yourself."));
304: 
305: 		String trxName = newTrx();
306: 		int updated = 0;
307: 		try {
308: 			for (Integer id : mappingIds(doc, trxName)) {
309: 				PO row = MTable.get(Env.getCtx(), T_SUPERVISOR).getPO(id.intValue(), trxName);
310: 				if (row == null)
311: 					continue;
312: 				set(row, "Supervisor_ID", Integer.valueOf(toUserId));
313: 				row.save();
314: 				updated++;
315: 			}
