498: 	/**
499: 	 * Carries out the chosen action on every ticked document.
500: 	 * <p>
501: 	 * One failing document does not stop the others: each is reported at the end
502: 	 * so the approver knows exactly what happened to every one of them.
503: 	 */
504: 	private void submit() {
505: 		List<ApprovalDocument> picked = checked();
506: 		if (picked.isEmpty()) {
507: 			showInfo(msg("Please tick at least one document."));
508: 			return;
509: 		}
510: 
511: 		String action = textOf(fAction);
512: 		String message = fMessage == null ? null : fMessage.getValue();
513: 		String forwardTo = textOf(fForwardTo);
514: 
515: 		if (DocumentApprovalService.ACTION_REJECT.equals(action) && isEmpty(message)) {
516: 			Messagebox.showDialog(msg("A message is required when rejecting a document."),
517: 					msg("Document Approval Form"), Messagebox.OK, Messagebox.EXCLAMATION);
518: 			return;
519: 		}
520: 		if (!isEmpty(forwardTo) && picked.size() > 1) {
521: 			Messagebox.showDialog(msg("Forwarding is done one document at a time."),
522: 					msg("Document Approval Form"), Messagebox.OK, Messagebox.EXCLAMATION);
523: 			return;
524: 		}
525: 
526: 		int done = 0;
527: 		StringBuilder problems = new StringBuilder();
528: 		for (ApprovalDocument doc : picked) {
529: 			try {
530: 				if (!isEmpty(forwardTo))
531: 					service.forward(doc, service.userIdByName(forwardTo));
532: 				else if (DocumentApprovalService.ACTION_REJECT.equals(action))
533: 					service.reject(doc, message);
534: 				else
535: 					service.approve(doc, message);
536: 				done++;
537: 			} catch (ApprovalException e) {
538: 				problems.append(doc.getDocumentNo()).append(": ").append(e.getMessage()).append('\n');
539: 			} catch (Exception e) {
540: 				log.warning("The approval of " + doc.getDocumentNo() + " failed: " + e.getMessage());
541: 				problems.append(doc.getDocumentNo()).append(": ")
542: 				         .append(msg("Unexpected error")).append('\n');
543: 			}
544: 		}
545: 
546: 		if (problems.length() > 0) {
547: 			Messagebox.showDialog(problems.toString(), msg("Document Approval Form"),
548: 					Messagebox.OK, Messagebox.ERROR);
549: 		} else {
550: 			showInfo(msg("Done. Documents processed: ") + done);
551: 		}
552: 		reload();
553: 	}
