143: 		StringBuilder sql = new StringBuilder();
144: 		sql.append("SELECT r.C_RfQ_ID, ").append(docNoExpr()).append(", r.Name, r.Created, ");
145: 		sql.append("(SELECT COUNT(*) FROM C_RfQResponse x WHERE x.C_RfQ_ID=r.C_RfQ_ID AND x.IsActive='Y'), ");
146: 		sql.append("(SELECT bp.Name FROM C_RfQResponse w JOIN C_BPartner bp ON bp.C_BPartner_ID=w.C_BPartner_ID ");
147: 		sql.append("  WHERE w.C_RfQ_ID=r.C_RfQ_ID AND w.IsActive='Y' AND w.IsSelectedWinner='Y' LIMIT 1), ");
148: 		sql.append(lastActionSql()).append(" AS la ");
149: 		sql.append("FROM C_RfQ r WHERE r.AD_Client_ID=? AND r.IsActive='Y' ");
150: 		sql.append("AND EXISTS (SELECT 1 FROM C_RfQResponse a WHERE a.C_RfQ_ID=r.C_RfQ_ID AND a.IsActive='Y') ");
