303: 	private void loadPrices(Comparison c) {
304: 		Map<Integer, Item> byLine = new HashMap<Integer, Item>();
305: 		for (Item it : c.items) byLine.put(it.rfqLineId, it);
306: 		String sql = "SELECT x.C_RfQResponse_ID, sl.C_RfQLine_ID, COALESCE(sq.Price,0), "
307: 				+ "COALESCE(sq.XX_NegotiatePrice,0), COALESCE(sq.XX_QuotationQty,0), COALESCE(sq.XX_VATAmt,0) "
308: 				+ "FROM C_RfQResponse x "
309: 				+ "JOIN C_RfQResponseLine sl ON sl.C_RfQResponse_ID=x.C_RfQResponse_ID AND sl.IsActive='Y' "
310: 				+ "JOIN C_RfQResponseLineQty sq ON sq.C_RfQResponseLine_ID=sl.C_RfQResponseLine_ID AND sq.IsActive='Y' "
311: 				+ "WHERE x.C_RfQ_ID=? AND x.IsActive='Y'";
312: 		PreparedStatement ps = null;
313: 		ResultSet rs = null;
314: 		try {
315: 			ps = DB.prepareStatement(sql, null);
316: 			ps.setInt(1, c.rfqId);
317: 			rs = ps.executeQuery();
318: 			while (rs.next()) {
319: 				Item it = byLine.get(rs.getInt(2));
320: 				if (it == null) continue;
321: 				Integer resp = Integer.valueOf(rs.getInt(1));
322: 				if (it.unit.containsKey(resp)) continue; // one LineQty per line expected
323: 				BigDecimal price = rs.getBigDecimal(3);
324: 				BigDecimal neg = rs.getBigDecimal(4);
325: 				BigDecimal unit = neg.signum() > 0 ? neg : price;
326: 				BigDecimal qty = rs.getBigDecimal(5).signum() > 0 ? rs.getBigDecimal(5) : it.qty;
327: 				if (unit.signum() <= 0) continue; // supplier did not quote this item
328: 				it.unit.put(resp, unit);
329: 				it.total.put(resp, unit.multiply(qty).setScale(2, RoundingMode.HALF_UP));
330: 				it.vat.put(resp, rs.getBigDecimal(6));
331: 			}
332: 		} catch (Exception e) {
333: 			log.severe("loadPrices: " + e.getMessage());
334: 		} finally {
335: 			DB.close(rs, ps);
336: 		}
337: 		for (Item it : c.items) { // lowest unit price per item (ties all highlighted)
338: 			BigDecimal min = null;
339: 			for (BigDecimal u : it.unit.values())
340: 				if (min == null || u.compareTo(min) < 0) min = u;
341: 			if (min != null)
342: 				for (Map.Entry<Integer, BigDecimal> e : it.unit.entrySet())
343: 					if (e.getValue().compareTo(min) == 0) it.lowest.add(e.getKey());
344: 		}
345: 	}
