347: 	private void computeTotals(Comparison c) {
348: 		for (Supplier s : c.suppliers) {
349: 			Integer k = Integer.valueOf(s.responseId);
350: 			for (Item it : c.items) {
351: 				if (it.total.get(k) != null) s.subTotal = s.subTotal.add(it.total.get(k));
352: 				if (it.vat.get(k) != null) s.vat = s.vat.add(it.vat.get(k));
353: 			}
354: 			s.discount = s.pctDiscount
355: 					? s.subTotal.add(s.vat).multiply(s.discountInput).divide(HUNDRED, 2, RoundingMode.HALF_UP)
356: 					: s.discountInput;
357: 			s.grand = s.subTotal.subtract(s.discount).add(s.transport).add(s.other);
358: 			s.ownership = s.grand.add(s.vat);
359: 		}
360: 	}
