411: 	/** Mark one supplier as winner (only one per RFQ) and log it. */
412: 	public void recommendWinner(int rfqId, int responseId, String remarks) throws Exception {
413: 		String trxName = Trx.createTrxName("RfQWin");
414: 		Trx trx = Trx.get(trxName, true);
415: 		try {
416: 			if (DB.getSQLValue(trxName, "SELECT COUNT(*) FROM C_RfQResponse WHERE C_RfQResponse_ID=? "
417: 					+ "AND C_RfQ_ID=? AND IsActive='Y' AND IsComplete='Y'", responseId, rfqId) == 0)
418: 				throw new Exception("Only a completed response of this RFQ can be recommended.");
419: 			DB.executeUpdateEx("UPDATE C_RfQResponse SET IsSelectedWinner='N' WHERE C_RfQ_ID=?",
420: 					new Object[] { rfqId }, trxName);
421: 			DB.executeUpdateEx("UPDATE C_RfQResponse SET IsSelectedWinner='Y' WHERE C_RfQResponse_ID=?",
422: 					new Object[] { responseId }, trxName);
423: 			trx.commit();
424: 		} catch (Exception e) {
425: 			trx.rollback();
426: 			throw e;
427: 		} finally {
428: 			trx.close();
429: 		}
430: 		String bp = DB.getSQLValueString(null, "SELECT bp.Name FROM C_RfQResponse x "
431: 				+ "JOIN C_BPartner bp ON bp.C_BPartner_ID=x.C_BPartner_ID WHERE x.C_RfQResponse_ID=?", responseId);
432: 		logHistory(rfqId, A_RECOMMEND, "Winner: " + bp + (isFilled(remarks) ? " | " + remarks.trim() : ""), 0);
433: 	}
