188: 	/**
189: 	 * RFQ Term dropdown. Source table: the one behind the RFQ Term column of C_RfQ (if the
190: 	 * dictionary has one), otherwise XX_RFQ_Term. Selecting a term fills Terms and Conditions.
191: 	 */
192: 	private void initTerms() {
193: 		PreparedStatement pstmt = null;
194: 		ResultSet rs = null;
195: 		int refId = 0;
196: 		int refValueId = 0;
197: 		try {
198: 			pstmt = DB.prepareStatement(
199: 					"SELECT ColumnName, AD_Reference_ID, AD_Reference_Value_ID "
200: 					+ "FROM AD_Column WHERE AD_Table_ID=(SELECT AD_Table_ID FROM AD_Table WHERE TableName='C_RfQ') "
201: 					+ "AND IsActive='Y' AND LOWER(ColumnName) LIKE '%term%' AND LOWER(ColumnName) LIKE '%_id' "
202: 					+ "ORDER BY AD_Column_ID", null);
203: 			rs = pstmt.executeQuery();
204: 			if (rs.next()) {
205: 				termColName = rs.getString(1);
206: 				refId = rs.getInt(2);
207: 				refValueId = rs.getInt(3);
208: 			}
209: 		} catch (SQLException e) {
210: 			log.log(Level.WARNING, "RFQ Term column lookup failed", e);
211: 		} finally {
212: 			DB.close(rs, pstmt);
213: 		}
214: 
215: 		if (termColName != null) {
216: 			if (refId == DisplayType.Table && refValueId > 0) {
217: 				termTable = DB.getSQLValueString(null,
218: 						"SELECT t.TableName FROM AD_Ref_Table rt JOIN AD_Table t ON t.AD_Table_ID=rt.AD_Table_ID "
219: 						+ "WHERE rt.AD_Reference_ID=?", refValueId);
220: 				termIdCol = DB.getSQLValueString(null,
221: 						"SELECT k.ColumnName FROM AD_Ref_Table rt JOIN AD_Column k ON k.AD_Column_ID=rt.AD_Key "
222: 						+ "WHERE rt.AD_Reference_ID=?", refValueId);
223: 			} else if (termColName.toLowerCase().endsWith("_id")) {
224: 				termTable = termColName.substring(0, termColName.length() - 3);
225: 				termIdCol = termColName;
226: 			}
227: 		}
228: 		if (termTable == null || termIdCol == null || !columnExists(termTable, termIdCol)) {
229: 			// no term column on C_RfQ: use the XX_RFQ_Term table (Name + TermsText)
230: 			termTable = "XX_RFQ_Term";
231: 			termIdCol = "XX_RFQ_Term_ID";
232: 		}
233: 
234: 		for (String cand : TERM_TEXT_CANDIDATES) {
235: 			if (columnExists(termTable, cand)) {
236: 				termTextCol = cand;
237: 				break;
238: 			}
239: 		}
240: 		if (termTextCol == null)
241: 			termTextCol = DB.getSQLValueString(null,
242: 					"SELECT column_name FROM information_schema.columns "
243: 					+ "WHERE LOWER(table_name)=LOWER(?) AND (data_type='text' OR character_maximum_length>=255) "
244: 					+ "ORDER BY ordinal_position LIMIT 1", termTable);
245: 		log.info("RFQ Term source: column=" + termColName + ", table=" + termTable
246: 				+ ", key=" + termIdCol + ", text=" + termTextCol);
247: 
248: 		termCombo.setMold("select");
249: 		termCombo.appendChild(new Listitem("", Integer.valueOf(0)));
250: 		boolean hasClient = columnExists(termTable, "AD_Client_ID");
251: 		String sql = "SELECT " + termIdCol + ", Name FROM " + termTable
252: 				+ " WHERE IsActive='Y'" + (hasClient ? " AND AD_Client_ID IN (0,?)" : "") + " ORDER BY Name";
253: 		PreparedStatement ps2 = null;
254: 		ResultSet rs2 = null;
255: 		try {
256: 			ps2 = DB.prepareStatement(sql, null);
257: 			if (hasClient)
258: 				ps2.setInt(1, Env.getAD_Client_ID(Env.getCtx()));
259: 			rs2 = ps2.executeQuery();
260: 			while (rs2.next())
261: 				termCombo.appendChild(new Listitem(rs2.getString(2), Integer.valueOf(rs2.getInt(1))));
262: 		} catch (SQLException e) {
263: 			// form still works if the term table is missing; dropdown stays empty
264: 			log.log(Level.WARNING, "RFQ Term read failed: " + sql, e);
265: 		} finally {
266: 			DB.close(rs2, ps2);
267: 		}
268: 		termCombo.setSelectedIndex(0);
269: 		termCombo.addEventListener(Events.ON_SELECT, this);
270: 	}
