441: 	/** Follows the RequisitionRFQService eligibility rule */
442: 	private List<LineRow> loadRequisitionLines(int requisitionId, Set<Integer> skipLineIds) {
443: 		List<LineRow> result = new ArrayList<LineRow>();
444: 
445: 		StringBuilder sql = new StringBuilder();
446: 		sql.append("SELECT rl.M_RequisitionLine_ID, rl.M_Product_ID, p.Name, rl.C_UOM_ID, u.Name, ");
447: 		sql.append("rl.Qty, rl.Description, rl.M_AttributeSetInstance_ID, rl.M_Requisition_ID ");
448: 		sql.append("FROM M_RequisitionLine rl ");
449: 		sql.append("JOIN M_Product p ON p.M_Product_ID = rl.M_Product_ID ");
450: 		sql.append("LEFT JOIN C_UOM u ON u.C_UOM_ID = rl.C_UOM_ID ");
451: 		sql.append("WHERE rl.M_Requisition_ID=? AND rl.IsActive='Y' AND rl.C_OrderLine_ID IS NULL ");
452: 		if (reqLineHasRfqCol)
453: 			sql.append("AND (rl.XX_RfQ_ID IS NULL OR rl.XX_RfQ_ID=0) ");
454: 		sql.append("ORDER BY rl.Line");
455: 
456: 		PreparedStatement pstmt = null;
457: 		ResultSet rs = null;
458: 		try {
459: 			pstmt = DB.prepareStatement(sql.toString(), null);
460: 			pstmt.setInt(1, requisitionId);
461: 			rs = pstmt.executeQuery();
462: 			while (rs.next()) {
463: 				int lineId = rs.getInt(1);
464: 				if (skipLineIds.contains(Integer.valueOf(lineId)))
465: 					continue;
466: 				LineRow r = new LineRow();
467: 				r.reqLineId = lineId;
468: 				r.productId = rs.getInt(2);
469: 				r.productName = rs.getString(3);
470: 				r.uomId = rs.getInt(4);
471: 				r.uomName = rs.getString(5);
472: 				r.qty = rs.getBigDecimal(6) != null ? rs.getBigDecimal(6) : BigDecimal.ONE;
473: 				r.desc = rs.getString(7);
474: 				r.asiId = rs.getInt(8);
475: 				r.reqId = rs.getInt(9);
476: 				result.add(r);
477: 			}
478: 		} catch (SQLException e) {
479: 			log.log(Level.SEVERE, sql.toString(), e);
480: 			throw new AdempiereException(e);
481: 		} finally {
482: 			DB.close(rs, pstmt);
483: 		}
484: 		return result;
485: 	}
