487: 	/** Popup "Add Line": moves ticked lines into the lines table. */
488: 	private void addSelectedLines() {
489: 		if (popupList == null)
490: 			return;
491: 		if (popupList.getSelectedCount() == 0) {
492: 			warn("Select at least one line.");
493: 			return;
494: 		}
495: 
496: 		Set<Integer> existing = new HashSet<Integer>();
497: 		for (Listitem it : rfqList.getItems())
498: 			existing.add(Integer.valueOf(((LineRow) it.getValue()).reqLineId));
499: 
500: 		for (Listitem src : new ArrayList<Listitem>(popupList.getSelectedItems())) {
501: 			LineRow s = (LineRow) src.getValue();
502: 			if (existing.contains(Integer.valueOf(s.reqLineId)))
503: 				continue;
504: 
505: 			LineRow r = new LineRow();
506: 			r.reqId = s.reqId;
507: 			r.reqLineId = s.reqLineId;
508: 			r.productId = s.productId;
509: 			r.productName = s.productName;
510: 			r.uomId = s.uomId;
511: 			r.uomName = s.uomName;
512: 			r.asiId = s.asiId;
513: 			r.qty = s.qty;
514: 			r.desc = s.desc;
515: 			r.qtyBox = new Decimalbox(s.qty);
516: 			r.qtyBox.setWidth("90px");
517: 
518: 			int serial = rfqList.getItemCount() + 1;
519: 
520: 			Listitem item = new Listitem();
521: 			item.setValue(r);
522: 			item.appendChild(new Listcell(String.valueOf(serial)));
523: 			item.appendChild(new Listcell(String.valueOf(r.reqId)));
524: 			item.appendChild(new Listcell(String.valueOf(r.productId)));
525: 			item.appendChild(new Listcell(nvl(r.productName)));
526: 			Listcell qtyCell = new Listcell();
527: 			qtyCell.appendChild(r.qtyBox);
528: 			item.appendChild(qtyCell);
529: 			rfqList.appendChild(item);
530: 			item.setSelected(true);   // newly added lines are ticked by default
531: 		}
532: 		closePopup();
533: 	}
